using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;

sealed class MistakeEntry {
 public int Id,Attempts;public bool Challenge,Resolved;public string Title,Category,FirstSeen,LastSeen,ResolvedAt;public Evaluation Failure;
 public string Key{get{return (Challenge?"dark-":"practice-")+Id;}}
}
static class MistakeBook {
 static JavaScriptSerializer Serializer(){return new JavaScriptSerializer{MaxJsonLength=12000000,RecursionLimit=100};}
 static string Root{get{return Path.Combine(Engine.DataRoot,"mistakes-ver1.3");}}
 public static List<MistakeEntry> Load(){var list=new List<MistakeEntry>();if(!Directory.Exists(Root))return list;foreach(string path in Directory.GetFiles(Root,"*.json")){try{if(new FileInfo(path).Length>8000000)continue;var item=Serializer().Deserialize<MistakeEntry>(File.ReadAllText(path,Encoding.UTF8));if(item!=null&&item.Failure!=null)list.Add(item);}catch{}}return list.OrderByDescending(x=>x.LastSeen).ToList();}
 public static void Record(Problem problem,Evaluation ev,bool challenge){bool failed=!ev.Compiled||ev.Cases.Count==0||ev.Cases.Any(c=>!c.Passed);string key=(challenge?"dark-":"practice-")+problem.Id;var previous=Load().FirstOrDefault(x=>x.Key==key);if(!failed&&previous==null)return;string now=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");var entry=previous??new MistakeEntry{Id=problem.Id,Challenge=challenge,Title=problem.Title,Category=problem.Category,FirstSeen=now};if(failed){entry.Attempts++;entry.LastSeen=now;entry.Resolved=false;entry.ResolvedAt=null;var snapshot=new Evaluation{ProblemId=ev.ProblemId,Code=ev.Code,Compiler=ev.Compiler,Compiled=ev.Compiled,Score=ev.Score,Seed=ev.Seed,Title=ev.Title,Time=ev.Time};snapshot.Cases=ev.Cases.Where(c=>!c.Passed).Take(3).ToList();entry.Failure=snapshot;}else{entry.Resolved=true;entry.ResolvedAt=now;}Save(entry);}
 static void Save(MistakeEntry entry){Directory.CreateDirectory(Root);string path=Path.Combine(Root,entry.Key+".json"),temp=path+".tmp";File.WriteAllText(temp,Serializer().Serialize(entry),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 public static void Remove(MistakeEntry entry){string path=Path.Combine(Root,entry.Key+".json");if(File.Exists(path))File.Delete(path);}
}

sealed class MistakeWindow : Window {
 ListBox list;ComboBox filter;TextBox search,details;CodeEditor code;TextBlock count;MistakeEntry selected;Action<MistakeEntry,bool> retry;
 public MistakeWindow(Action<MistakeEntry,bool> onRetry){retry=onRetry;Title="错题本";Width=1050;Height=760;MinWidth=780;MinHeight=540;WindowStartupLocation=WindowStartupLocation.CenterOwner;Theme.Window(this);var root=new Grid{Margin=new System.Windows.Thickness(20)};root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});Content=root;
 var bar=new DockPanel{Margin=new Thickness(0,0,0,14)};var tools=new StackPanel{Orientation=Orientation.Horizontal};filter=new ComboBox{MinWidth=125,Margin=new Thickness(8,0,8,0)};foreach(var s in new[]{"待巩固","已解决","全部记录"})filter.Items.Add(s);filter.SelectedIndex=0;Dark.StyleLightCombo(filter);tools.Children.Add(filter);search=new TextBox{Width=175,Padding=new Thickness(8),ToolTip="搜索题目 / 题号"};tools.Children.Add(search);DockPanel.SetDock(tools,Dock.Right);bar.Children.Add(tools);count=Theme.Text("错题本",18,Theme.Blue,true);bar.Children.Add(count);root.Children.Add(bar);
 var panes=new Grid();panes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(240)});panes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(16)});panes.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});Grid.SetRow(panes,1);root.Children.Add(panes);list=new ListBox{BorderThickness=new Thickness(0),Background=System.Windows.Media.Brushes.Transparent,HorizontalContentAlignment=HorizontalAlignment.Stretch};panes.Children.Add(list);var right=new Grid();right.RowDefinitions.Add(new RowDefinition{Height=new GridLength(130)});right.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});right.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});Grid.SetColumn(right,2);panes.Children.Add(right);details=new TextBox{IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Background=Theme.White,BorderBrush=Theme.Line,Padding=new Thickness(10),Text="没有待巩固的错题。编译失败或测试未通过时会自动记录。"};right.Children.Add(details);code=new CodeEditor();code.Input.IsReadOnly=true;Grid.SetRow(code,1);right.Children.Add(code);var actions=new WrapPanel{Margin=new Thickness(0,12,0,0)};var again=Theme.Button("重新练习",true);again.Click+=(s,e)=>Retry(false);var restore=Theme.Button("恢复失败代码");restore.Click+=(s,e)=>Retry(true);var compare=PracticeTools.Icon("失败用例对比",PracticeTools.Compare,()=>{if(selected!=null)new ComparisonWindow(selected.Failure){Owner=this}.ShowDialog();});var remove=Theme.Button("删除记录");remove.Click+=(s,e)=>{if(selected==null)return;if(AppDialog.Show(this,"删除这条错题记录？不会删除草稿或历史最高分。","删除记录",MessageBoxButton.YesNo)==MessageBoxResult.Yes)try{MistakeBook.Remove(selected);Populate();}catch(Exception ex){AppDialog.Show(this,ex.Message,"保存失败");}};again.IsEnabled=restore.IsEnabled=compare.IsEnabled=remove.IsEnabled=false;actions.Children.Add(again);actions.Children.Add(restore);actions.Children.Add(compare);actions.Children.Add(remove);Grid.SetRow(actions,2);right.Children.Add(actions);list.SelectionChanged+=(s,e)=>{selected=list.SelectedItem is ListBoxItem?(MistakeEntry)((ListBoxItem)list.SelectedItem).Tag:null;again.IsEnabled=compare.IsEnabled=remove.IsEnabled=selected!=null;restore.IsEnabled=selected!=null&&!selected.Challenge;if(selected==null){code.Text="";details.Text="没有匹配的错题记录。";return;}code.Text=selected.Failure.Code??"";details.Text=selected.Title+" · "+(selected.Challenge?"暗域闯关":"普通练习")+"\n"+(selected.Resolved?"已解决":"待巩固")+" · "+selected.Attempts+" 次失败 · "+selected.LastSeen+"\n"+"最近失败得分："+selected.Failure.Score.ToString("0.#")+"\n"+(!selected.Failure.Compiled?Theme.CompileAdvice(selected.Failure.Compiler,false):string.Join("\n",selected.Failure.Cases.Select(c=>c.Diagnosis)))+"\n"+"保留最近一次失败的代码和最多三个失败用例；暗域代码只读，不可导入。";};filter.SelectionChanged+=(s,e)=>Populate();search.TextChanged+=(s,e)=>Populate();Populate();}
 void Populate(){if(list==null)return;int prior=selected==null?-1:selected.Id;bool dark=selected!=null&&selected.Challenge;var all=MistakeBook.Load();string query=search.Text.Trim();list.Items.Clear();foreach(var e in all.Where(x=>(filter.SelectedIndex==2||x.Resolved==(filter.SelectedIndex==1))&&(query==""||x.Title.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||L.T(x.Title).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0||x.Id.ToString().Contains(query))))list.Items.Add(new ListBoxItem{Tag=e,Content=Theme.Text((e.Challenge?"◆ "+(e.Id-100).ToString("00"):"○ "+e.Id.ToString("00"))+"  "+e.Title+"\n"+(e.Resolved?"已解决":"待巩固")+" · "+e.Attempts+" 次失败",12),Padding=new Thickness(8)});count.Text="错题本 · "+list.Items.Count;var item=list.Items.Cast<ListBoxItem>().FirstOrDefault(x=>((MistakeEntry)x.Tag).Id==prior&&((MistakeEntry)x.Tag).Challenge==dark)??list.Items.Cast<ListBoxItem>().FirstOrDefault();list.SelectedItem=item;if(item==null){details.Text="没有匹配的错题记录。";code.Text="";}}
 void Retry(bool restore){if(selected==null||restore&&selected.Challenge)return;var entry=selected;PracticeTools.CloseThen(this,()=>retry(entry,restore));}
}
